class SensorException extends Exception {
    private final int sensorCode;
    public SensorException(String msg, int code) {
        super(msg);
        this.sensorCode = code;
    }
    public int getSensorCode() { return sensorCode; }
}
public class SensorMonitor {
    public static void main(String[] args) {
        try {
            throw new SensorException("Overheat", 502);
        } catch (SensorException e) {
            System.out.println(e.getMessage() + ":" + e.getSensorCode());
        }
    }
}
```

